    /// 自动识别英文单词或固定搭配并从内置词典检索准确中文翻译（含词形还原 Lemmatization）
    public static func lookupChineseDefinition(for rawEnglish: String) -> String? {
        let cleaned = rawEnglish
            .trimmingCharacters(in: .whitespacesAndNewlines)
            .trimmingCharacters(in: CharacterSet(charactersIn: ".,;:?!\"()[]{}-—'"))
            .replacingOccurrences(of: "\\s+", with: " ", options: .regularExpression)
            .lowercased()
        guard !cleaned.isEmpty else { return nil }

        if let exact = baseLookupTable[cleaned] {
            return exact
        }

        // Try candidate lemmatizations (plurals, -ed, -ing, -ly, British/American spelling variants)
        for candidate in candidateLemmas(for: cleaned) {
            if let hit = baseLookupTable[candidate] {
                return hit
            }
        }

        return nil
    }

    public static func candidateLemmas(for word: String) -> [String] {
        var candidates: [String] = []
        // British <-> American spelling normalization
        if word.hasSuffix("ise") {
            candidates.append(String(word.dropLast(3)) + "ize")
        } else if word.hasSuffix("ize") {
            candidates.append(String(word.dropLast(3)) + "ise")
        }
        if word.hasSuffix("isation") {
            candidates.append(String(word.dropLast(7)) + "ization")
        } else if word.hasSuffix("ization") {
            candidates.append(String(word.dropLast(7)) + "isation")
        }
        if word.contains("our") {
            candidates.append(word.replacingOccurrences(of: "our", with: "or"))
        }
        if word.hasSuffix("re") && word.count > 4 {
            candidates.append(String(word.dropLast(2)) + "er")
        }

        // Inflectional suffixes
        if word.hasSuffix("ies") && word.count > 4 {
            candidates.append(String(word.dropLast(3)) + "y")
        }
        if word.hasSuffix("es") && word.count > 3 {
            candidates.append(String(word.dropLast(2)))
            candidates.append(String(word.dropLast(1)))
        }
        if word.hasSuffix("s") && !word.hasSuffix("ss") && word.count > 3 {
            candidates.append(String(word.dropLast(1)))
        }
        if word.hasSuffix("ied") && word.count > 4 {
            candidates.append(String(word.dropLast(3)) + "y")
        }
        if word.hasSuffix("ed") && word.count > 3 {
            let stem = String(word.dropLast(2))
            candidates.append(stem)
            candidates.append(stem + "e")
            if stem.count >= 3 {
                let chars = Array(stem)
                if chars[chars.count - 1] == chars[chars.count - 2] {
                    candidates.append(String(chars.dropLast()))
                }
            }
        }
        if word.hasSuffix("ing") && word.count > 4 {
            let stem = String(word.dropLast(3))
            candidates.append(stem)
            candidates.append(stem + "e")
            if stem.count >= 3 {
                let chars = Array(stem)
                if chars[chars.count - 1] == chars[chars.count - 2] {
                    candidates.append(String(chars.dropLast()))
                }
            }
        }
        if word.hasSuffix("ly") && word.count > 4 {
            candidates.append(String(word.dropLast(2)))
            if word.hasSuffix("ily") && word.count > 5 {
                candidates.append(String(word.dropLast(3)) + "y")
            }
        }
        return candidates
    }

    /// 搜索内置词典中的词条
    public static func search(query: String, inBookID bookID: String? = nil) -> [VocabularyWord] {
        let books = bookID == nil ? allDictionaries : allDictionaries.filter { $0.id == bookID }
        let allWords = books.flatMap(\.words)
        let q = query.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !q.isEmpty else { return allWords }
        return allWords.filter {
            $0.word.localizedCaseInsensitiveContains(q)
                || $0.definitionZH.localizedCaseInsensitiveContains(q)
                || $0.exampleSentence.localizedCaseInsensitiveContains(q)
        }
    }
